 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            r0, c0 = min(x for x, _ in cells), min(y for _, y in cells)
            r1, c1 = max(x for x, _ in cells), max(y for _, y in cells)
            mask = frozenset((x-r0, y-c0) for x, y in cells)
            result.append((color, cells, (r0, c0), mask))
    return result


def _canonical(mask):
    transforms = []
    for k in range(8):
        pts = []
        for x, y in mask:
            if k == 0: a, b = x, y
            elif k == 1: a, b = x, -y
            elif k == 2: a, b = -x, y
            elif k == 3: a, b = -x, -y
            elif k == 4: a, b = y, x
            elif k == 5: a, b = y, -x
            elif k == 6: a, b = -y, x
            else: a, b = -y, -x
            pts.append((a, b))
        a0, b0 = min(a for a, b in pts), min(b for a, b in pts)
        transforms.append(tuple(sorted((a-a0, b-b0) for a, b in pts)))
    return min(transforms)


def transform(grid):
    out = [row[:] for row in grid]
    objs = _components(grid)
    byshape = {}
    for obj in objs:
        color, cells, pos, mask = obj
        byshape.setdefault(_canonical(mask), []).append(obj)
    candidates = []
    for group in byshape.values():
        if len(group) < 2:
            continue
        # The earlier copy is the one altered; the color halfway between
        # the paired colors is used as the blended color.
        group = sorted(group, key=lambda o: (o[2][0], o[2][1]))
        for a, b in zip(group, group[1:]):
            if a[0] == b[0]:
                continue
            dest = (a[0] + b[0]) // 2
            candidates.append((a[2], a, dest))
    if candidates:
        _, obj, dest = min(candidates, key=lambda z: z[0])
        for r, c in obj[1]:
            out[r][c] = dest
    return out


if __name__ == '__main__':
    pass
