 "new_string": "def transform(grid):
    out = [row[:] for row in grid]
    objs = _components(grid)
    if not objs:
        return out

    # A long straight/near-straight object acts as the color key.
    def longest_run(obj):
        cells = set(obj[1])
        best = 0
        for r, c in cells:
            for dr, dc in ((0, 1), (1, 0)):
                n = 1
                while (r + n*dr, c + n*dc) in cells:
                    n += 1
                best = max(best, n)
        return best

    by_color = {}
    for obj in objs:
        by_color.setdefault(obj[0], []).append(obj)
    marker = max(objs, key=lambda o: (longest_run(o), len(o[1]), -len(by_color[o[0]]), -o[2][0]))
    marker_color = marker[0]

    byshape = {}
    for obj in objs:
        byshape.setdefault(_canonical(obj[3]), []).append(obj)

    # The key object denotes the replacement color; recolor its matching
    # shape-copy (if present) to that color. Otherwise pick the most remote
    # copy from the repeated-shape families.
    group = byshape.get(_canonical(marker[3]), [])
    targets = [obj for obj in group if obj is not marker and obj[0] != marker_color]
    if not targets:
        groups = [g for g in byshape.values() if len(g) >= 2]
        targets = [obj for g in groups for obj in g if obj is not marker and obj[0] != marker_color]
        if targets:
            def distance(obj):
                return min(abs(r-r2) + abs(c-c2) for r, c in obj[1] for r2, c2 in marker[1])
            obj = max(targets, key=distance)
        else:
            return out
    else:
        obj = targets[0]
    for r, c in obj[1]:
        out[r][c] = marker_color
    return out
