    # the uppermost copy; the lower copy is the recolored one.
    candidates = []
    for group in groups.values():
        if len(group) < 2:
            continue
        group = sorted(group, key=lambda obj: obj[2])
        colors = {obj[0] for obj in group}
        if len(colors) < 2:
            continue
        # Prefer the largest repeated silhouette, then the largest family.
        candidates.append((len(group[0][1]), len(group), group))
