 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in set(sum(grid, []))}
    bg = max(counts, key=counts.get)
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            r0 = min(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            mask = frozenset((x-r0, y-c0) for x, y in cells)
            # Canonicalize over rotations/reflections to match oriented copies.
            forms = []
            for k in range(8):
                pts = []
                for x, y in mask:
                    pts.append(((x,y),(x,-y),(-x,y),(-x,-y),(y,x),(y,-x),(-y,x),(-y,-x))[k])
                a0, b0 = min(x for x, _ in pts), min(y for _, y in pts)
                forms.append(tuple(sorted((x-a0, y-b0) for x, y in pts)))
            objects.append((color, cells, (r0, c0), min(forms)))

    groups = {}
    for obj in objects:
        groups.setdefault(obj[3], []).append(obj)
    pairs = []
    for group in groups.values():
        if len({obj[0] for obj in group}) > 1:
            group = sorted(group, key=lambda obj: obj[2])
            for i, upper in enumerate(group):
                for lower in group[i+1:]:
                    if upper[0] != lower[0]:
                        pairs.append((upper, lower))
    out = [row[:] for row in grid]
    if pairs:
        upper, lower = min(pairs, key=lambda pair: (pair[0][2], pair[1][2]))
        for r, c in upper[1]:
            out[r][c] = lower[0]
    return out

